// A lesson corpus and a finding-case corpus with every shape the selection's
// filters, ranking and caps decide on — for F2's equivalence proof
// (two finds over the whole corpus select what S9a's per-row finds did).
// Deterministic: generated by index arithmetic, no randomness.
import type { FindHit } from "../../src/memory/selection.js";

export const CORPUS_ROOT = "viking://user/reviewer/memories";
export const CORPUS_EXP = `${CORPUS_ROOT}/experiences`;
export const CORPUS_CASES = `${CORPUS_ROOT}/finding-cases`;

/** The PR the corpus is selected for, and the files it changes. */
export const CORPUS_PR = 42;
export const CORPUS_PR_FILES = [
  "backend/api/views.py",
  "docs/guide.md",
  "frontend/app/page.tsx",
] as const;

const KINDS = ["dont-raise", "look-for", "repo-fact", "convention"] as const;
const LENSES = [
  "pass-baseline",
  "pass-security",
  "pass-sweep",
  "pass-ui",
  "pass-validate",
  "pass-concurrency",
  "pass-data-safety",
  "", // names no lens: for every lens
  "pass-baseline,pass-security",
  "pass-sweep,pass-validate",
];
const PATHS = ["**", "docs/**", "backend/**", "frontend/**", "nowhere/**", ""];

function typed(i: number, body: string): string {
  const kind = KINDS[i % KINDS.length]!;
  const lens = LENSES[(i * 3) % LENSES.length]!;
  const paths = PATHS[(i * 5) % PATHS.length]!;
  const evidence = Array.from({ length: (i % 4) + 1 }, (_, k) => `pr:${100 + i * 4 + k}`).join(",");
  const cls = `c${i % 7}.k${i % 3}`;
  return (
    `#lesson kind=${kind}` +
    (lens ? ` lens=${lens}` : "") +
    ` class=${cls}` +
    (paths ? ` paths=${paths}` : "") +
    ` evidence=${evidence}\n${body}`
  );
}

/** The lesson corpus: 72 typed lessons (some big enough to hit token caps)
 * and every special case — legacy shapes, retired, moved, unknown polarity,
 * not a lesson, out of the area, undated, duplicates. */
export function lessonCorpus(): FindHit[] {
  const hits: FindHit[] = [];
  for (let i = 0; i < 72; i++) {
    const day = String(1 + (i % 28)).padStart(2, "0");
    const month = i % 2 === 0 ? "09" : "10";
    const name = `2026${month}${day}T${String(i % 24).padStart(2, "0")}0000-l${i}.md`;
    const body = i % 6 === 0 ? `BIG ${"x".repeat(4400)}` : `Lesson ${i}.`;
    hits.push({ uri: `${CORPUS_EXP}/${name}`, score: ((i * 37) % 100) / 100, text: typed(i, body) });
  }
  const special = (name: string, text: string, score = 0.5, area = CORPUS_EXP): void => {
    hits.push({ uri: `${area}/${name}`, score, text });
  };
  special("20260901T000000-legacy-dr.md", "#lesson kind=dont-raise class=baseline.style evidence=pr:3\nNo style.");
  special("20260902T000000-legacy-lf.md", "#lesson kind=look-for class=missed.y evidence=pr:4\nLook for y.");
  special("20260903T000000-conv.md", "#convention #corpus topic=naming source=docs/x.md Use snake_case.");
  special("20260904T000000-retired.md", `#retired ${typed(0, "Retired.")}`);
  special("20260905T000000-moved.md", "#retired #moved moved-to=events/x.md\nThis entry moved.");
  special("20260906T000000-unknown.md", "#eod-learning Something learned, polarity never said.");
  special("20260907T000000-feedback.md", "#feedback kind=feedback pr=5 type: false-positive — no");
  special("20260908T000000-prose.md", "Just some prose about the repo.");
  special("undated-lesson.md", typed(1, "Undated."));
  special("20261006T120000-listed-retired.md", typed(2, "On the store's retired list."));
  special("20261006T130000-suppressed.md", typed(4, "The operator suppressed it."));
  // Out of the area: another area, a deeper path, an engine blurb, the dir.
  special("x.md", typed(5, "Pinned."), 0.9, `${CORPUS_ROOT}/preferences/pinned`);
  special("y.md", typed(6, "An event."), 0.9, `${CORPUS_ROOT}/events`);
  special(".abstract.md", "experiences overview", 0.99);
  hits.push({ uri: CORPUS_EXP, score: 0.99, text: "the area's own directory record" });
  // The same file returned twice (indexed more than once).
  hits.push({ ...hits[3]!, score: 0.01 });
  return hits;
}

/** URIs the corpus's selection tests put on the retired list / suppress. */
export const CORPUS_RETIRED = [`${CORPUS_EXP}/20261006T120000-listed-retired.md`];
export const CORPUS_SUPPRESSED = [`${CORPUS_EXP}/20261006T130000-suppressed.md`];

function caseText(i: number): string {
  const pr = i % 9 === 0 ? CORPUS_PR : 200 + i;
  const path =
    i % 5 === 4 ? "other/file.py" : CORPUS_PR_FILES[i % CORPUS_PR_FILES.length]!.replace(/ /g, "%20");
  const lens = ["pass-baseline", "pass-ui", "pass-concurrency", "pass-security"][i % 4]!;
  const posted = `2026-${i % 2 === 0 ? "09" : "10"}-${String(1 + (i % 27)).padStart(2, "0")}T10:00:00Z`;
  return (
    `${i % 13 === 12 ? "#retired " : ""}#case kind=case case=${pr}-r1-${i} pr=${pr} round=1 rounds=1 lens=${lens} ` +
    `finding_kind=scope severity=P2 path=${path} lines=10 fate=fixed posted=${posted} replies=${i % 6}\n` +
    (i % 7 === 0 ? `A long case. ${"y".repeat(1800)}` : `Case ${i}.`)
  );
}

/** The finding-case corpus: 40 cases (this PR's own, other paths, retired,
 * every lens and reply count) and one entry that is no case. */
export function caseCorpus(): FindHit[] {
  const hits: FindHit[] = Array.from({ length: 40 }, (_, i) => ({
    uri: `${CORPUS_CASES}/case-${200 + i}-r1-${i}.md`,
    score: ((i * 13) % 100) / 100,
    text: caseText(i),
  }));
  hits.push({ uri: `${CORPUS_CASES}/not-a-case.md`, score: 0.9, text: "#feedback not a case" });
  return hits;
}
